// GENERATED by scripts/extract-flash-text-metrics.mjs — do not edit by hand, except as noted.
//
// Flash's own single-line text metrics, recovered from the authored heights in
// the shipped window layouts. Each entry is a font size mapped to the line box
// Flash used for it, with the field's 2px top and bottom gutters removed.
//
// Only sizes where the layouts agree are listed: at least 10 single-line
// fields, at least 60% of them on the same height. Everything else falls back to
// measuring the font in the browser, which is what the whole port did before.
//
// HAND-ADDED, and the generator needs the same change: `[14, 15]`. The generator
// samples `<text>` windows only, which left size 14 with too few to clear the
// threshold — the window debugger reported it as "Flash 19, port 20 (+1)" on the
// navigator's `category_name`. Labels are authored to the same rule (measured:
// 134 of the 148 shipped labels sit at exactly `lineBox + 4`, none at `lineBox`),
// so counting them gives size 14 **157 samples, 65% agreeing on height 19**,
// which clears both thresholds. Re-running the generator over `<text>` alone
// would silently drop this row again; widen its element set first.
//
// The wider sample confirms every other row unchanged.
//
// TS-only: Flash's metrics lived inside the player; no AS3 source states them.

/** A flash.text.TextField reserves this much above AND below its text. */
export const FLASH_TEXT_GUTTER = 2;

/** font size -> the line box Flash advanced by, gutters excluded. */
export const FLASH_LINE_BOX: ReadonlyMap<number, number> = new Map([
    [9, 10],
    [10, 11],
    [11, 12],
    [12, 13],
    [13, 14],
    [14, 15],
    [16, 17],
    [18, 20],
    [20, 22],
    [24, 26],
]);

/**
 * Flash's line box for a size, or null when the layouts had nothing confident
 * to say about it.
 */
export function flashLineBox(fontSize: number): number | null
{
    return FLASH_LINE_BOX.get(Math.round(fontSize)) ?? null;
}
